const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  // Furnace Creek Visitor's Center, Death Valley, CA, USA
  const point = ee.Geometry.Point([-116.8665, 36.4626]);
  const startDate = '2013-06-30';
  const endDate = '2013-07-01'; // Exclusive end date

  // 2. Data Acquisition & Check
  // Use ERA5 Hourly for 2m air temperature, which is more accurate than LST.
  let era5Collection = ee.ImageCollection('ECMWF/ERA5/HOURLY')
    .filterDate(startDate, endDate)
    .filterBounds(point)
    .select('temperature_2m');

  const collectionSize = era5Collection.size().getInfo();
  if (collectionSize === 0) {
    console.log("Evidence: No ERA5 images found for the specified date and location.");
    console.log("A: No");
    return;
  }
  console.log(`Evidence: Found ${collectionSize} hourly images for 2013-06-30.`);

  // 3. Processing
  // Find the maximum temperature across all hourly images for the day.
  const maxTempImage = era5Collection.max();

  // 4. Calculation
  // Extract the temperature value at the point.
  // The native resolution is ~27.8km, so scale is not critical but set for safety.
  const tempStats = maxTempImage.reduceRegion({
    reducer: ee.Reducer.first(), // Use 'first' as it's a single point
    geometry: point,
    scale: 1000,
  });

  const tempKelvin = tempStats.get('temperature_2m').getInfo();

  // 5. Validation & Final Answer
  if (tempKelvin === null || tempKelvin === undefined) {
    console.log("Evidence: Could not retrieve temperature data from the location.");
    console.log("C3: Calculation Failure");
    return;
  }

  // Convert from Kelvin to Celsius
  const tempCelsius = tempKelvin - 273.15;
  console.log(`Evidence: Maximum Air Temperature (Kelvin): ${tempKelvin.toFixed(2)} K`);
  console.log(`Evidence: Maximum Air Temperature (Celsius): ${tempCelsius.toFixed(2)} °C`);
  console.log("Evidence: Threshold for 'Yes' is > 50.0 °C");

  if (tempCelsius > 50) {
    console.log("A: Yes");
  } else {
    console.log("B: No");
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
